#include <iostream>
#include <memory>

class Resource {
public:
    Resource() { std::cout << "Resource created\n"; }
    ~Resource() { std::cout << "Resource destroyed\n"; }
};

void use_resource(std::shared_ptr<Resource> ptr) {
    // The use_count is now 3 (sp1, sp2, and the parameter ptr).
    std::cout << "Inside function, use_count: " << ptr.use_count() << "\n";
} // ptr goes out of scope, ref count is atomically decremented.

int main() {
    std::shared_ptr<Resource> sp1;
    {
        auto sp2 = std::make_shared<Resource>();
        std::cout << "After creation, use_count: " << sp2.use_count() << "\n"; // is 1
        sp1 = sp2; // Copy assignment, ref count is now 2
        std::cout << "After assignment, use_count: " << sp1.use_count() << "\n"; // is 2
        use_resource(sp1); // Pass by value, ref count is 3 inside function
        std::cout << "After function call, use_count: " << sp1.use_count() << "\n"; // back to 2
    } // sp2 goes out of scope, ref count becomes 1
    std::cout << "After inner scope, use_count: " << sp1.use_count() << "\n"; // is 1
    sp1.reset(); // Manually release ownership, ref count becomes 0, Resource destroyed
    std::cout << "After reset, use_count: " << sp1.use_count() << "\n"; // is 0
    return 0;
}
